<?php
namespace App\Services;
use App\Models\WebhookRequest;use Illuminate\Support\Facades\Http;use RuntimeException;
class ReplayService {public function execute(WebhookRequest $request,string $url,array $headers=[],mixed $payload=null){$this->safe($url);$start=hrtime(true);$method=$request->method;$body=$payload??$request->json_body;$client=Http::timeout((int)config('webhook.replay_timeout',10))->withHeaders($headers);$response=in_array($method,['GET','HEAD'],true)?$client->send($method,$url):$client->send($method,$url,['json'=>$body??[]]);return $request->replays()->create(['target_url'=>$url,'method'=>$method,'headers'=>$headers,'payload'=>is_array($body)?$body:null,'response_status'=>$response->status(),'response_headers'=>$response->headers(),'response_body'=>$response->body(),'duration_ms'=>(int)round((hrtime(true)-$start)/1000000),'executed_at'=>now()]);}private function safe(string $url):void{$p=parse_url($url);if(!$p||!in_array(strtolower($p['scheme']??''),['http','https'],true)||empty($p['host']))throw new RuntimeException('Only HTTP and HTTPS target URLs are allowed.');$h=strtolower($p['host']);if(in_array($h,['localhost','localhost.localdomain','ip6-localhost','ip6-loopback'],true)||str_ends_with($h,'.local'))throw new RuntimeException('Local targets are not allowed.');if(filter_var($h,FILTER_VALIDATE_IP)){if(!$this->public($h))throw new RuntimeException('Private or reserved IPs are not allowed.');return;}$records=dns_get_record($h,DNS_A|DNS_AAAA);if($records===false)throw new RuntimeException('Unable to resolve target host.');foreach($records as $r){$ip=$r['ip']??$r['ipv6']??null;if($ip&&!$this->public($ip))throw new RuntimeException('Target resolves to a private or reserved IP.');}}private function public(string $ip):bool{return filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)!==false;}}